-- S9 transactions (14.3 commit / 14.4 rollback / 4.28 SQL-transactions): what one session can observe; two-session checks are in the Concurrency harness
-- @s09_14_3_commit_work
DROP TABLE IF EXISTS t92_w9_c01; CREATE TABLE t92_w9_c01 (id INTEGER, a INTEGER, PRIMARY KEY (id)); BEGIN; INSERT INTO t92_w9_c01 VALUES (1, 1); COMMIT WORK; SELECT * FROM t92_w9_c01; DROP TABLE t92_w9_c01;
-- @s09_14_4_rollback_work_insert
DROP TABLE IF EXISTS t92_w9_c02; CREATE TABLE t92_w9_c02 (id INTEGER, a INTEGER, PRIMARY KEY (id)); BEGIN; INSERT INTO t92_w9_c02 VALUES (1, 1); ROLLBACK WORK; SELECT * FROM t92_w9_c02; DROP TABLE t92_w9_c02;
-- @s09_14_4_rollback_update_delete
DROP TABLE IF EXISTS t92_w9_c03; CREATE TABLE t92_w9_c03 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w9_c03 VALUES (1, 1); INSERT INTO t92_w9_c03 VALUES (2, 2); BEGIN; UPDATE t92_w9_c03 SET a = 100 WHERE id = 1; DELETE FROM t92_w9_c03 WHERE id = 2; ROLLBACK; SELECT * FROM t92_w9_c03; DROP TABLE t92_w9_c03;
-- @s09_14_4_rollback_scan_update
DROP TABLE IF EXISTS t92_w9_c04; CREATE TABLE t92_w9_c04 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w9_c04 VALUES (1, 1); INSERT INTO t92_w9_c04 VALUES (2, 2); BEGIN; UPDATE t92_w9_c04 SET a = a + 100; ROLLBACK; SELECT * FROM t92_w9_c04; DROP TABLE t92_w9_c04;
-- @s09_read_own_insert_by_pk
DROP TABLE IF EXISTS t92_w9_c05; CREATE TABLE t92_w9_c05 (id INTEGER, a INTEGER, PRIMARY KEY (id)); BEGIN; INSERT INTO t92_w9_c05 VALUES (1, 1); SELECT * FROM t92_w9_c05 WHERE id = 1; COMMIT; DROP TABLE t92_w9_c05;
-- @s09_read_own_insert_by_scan
DROP TABLE IF EXISTS t92_w9_c06; CREATE TABLE t92_w9_c06 (id INTEGER, a INTEGER, PRIMARY KEY (id)); BEGIN; INSERT INTO t92_w9_c06 VALUES (1, 1); SELECT * FROM t92_w9_c06; COMMIT; DROP TABLE t92_w9_c06;
-- @s09_read_own_update_by_scan
DROP TABLE IF EXISTS t92_w9_c07; CREATE TABLE t92_w9_c07 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w9_c07 VALUES (1, 1); BEGIN; UPDATE t92_w9_c07 SET a = 5 WHERE id = 1; SELECT COUNT(*) FROM t92_w9_c07 WHERE a = 5; COMMIT; DROP TABLE t92_w9_c07;
-- @s09_two_scan_updates_same_tx
DROP TABLE IF EXISTS t92_w9_c08; CREATE TABLE t92_w9_c08 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w9_c08 VALUES (1, 1); INSERT INTO t92_w9_c08 VALUES (2, 2); BEGIN; UPDATE t92_w9_c08 SET a = a + 1; UPDATE t92_w9_c08 SET a = a * 10; COMMIT; SELECT * FROM t92_w9_c08; DROP TABLE t92_w9_c08;
-- @s09_insert_then_scan_delete_same_tx
DROP TABLE IF EXISTS t92_w9_c09; CREATE TABLE t92_w9_c09 (id INTEGER, a INTEGER, PRIMARY KEY (id)); BEGIN; INSERT INTO t92_w9_c09 VALUES (1, 1); DELETE FROM t92_w9_c09 WHERE a = 1; COMMIT; SELECT COUNT(*) FROM t92_w9_c09; DROP TABLE t92_w9_c09;
-- @s09_error_aborts_tx
DROP TABLE IF EXISTS t92_w9_c10; CREATE TABLE t92_w9_c10 (id INTEGER, a INTEGER, PRIMARY KEY (id)); BEGIN; INSERT INTO t92_w9_c10 VALUES (1, 1); INSERT INTO t92_w9_c10 VALUES (1, 2); INSERT INTO t92_w9_c10 VALUES (2, 2); COMMIT; SELECT * FROM t92_w9_c10; DROP TABLE t92_w9_c10;
-- @s09_error_then_commit_reports_rollback
DROP TABLE IF EXISTS t92_w9_c11; CREATE TABLE t92_w9_c11 (id INTEGER, a INTEGER, PRIMARY KEY (id)); BEGIN; INSERT INTO t92_w9_c11 VALUES (1, 1); SELECT 1 / 0; COMMIT; SELECT COUNT(*) FROM t92_w9_c11; DROP TABLE t92_w9_c11;
-- @s09_autocommit_statement_atomic
DROP TABLE IF EXISTS t92_w9_c12; CREATE TABLE t92_w9_c12 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w9_c12 VALUES (1, 1); INSERT INTO t92_w9_c12 VALUES (2, 1); INSERT INTO t92_w9_c12 VALUES (1, 9), (3, 9); SELECT * FROM t92_w9_c12; DROP TABLE t92_w9_c12;
-- @s09_savepoint_rollback_to_after_write
DROP TABLE IF EXISTS t92_w9_c13; CREATE TABLE t92_w9_c13 (id INTEGER, a INTEGER, PRIMARY KEY (id)); BEGIN; INSERT INTO t92_w9_c13 VALUES (1, 1); SAVEPOINT s1; INSERT INTO t92_w9_c13 VALUES (2, 2); ROLLBACK TO SAVEPOINT s1; COMMIT; SELECT * FROM t92_w9_c13; DROP TABLE t92_w9_c13;
-- @s09_savepoint_rollback_to_no_write
DROP TABLE IF EXISTS t92_w9_c14; CREATE TABLE t92_w9_c14 (id INTEGER, a INTEGER, PRIMARY KEY (id)); BEGIN; INSERT INTO t92_w9_c14 VALUES (1, 1); SAVEPOINT s1; ROLLBACK TO SAVEPOINT s1; COMMIT; SELECT * FROM t92_w9_c14; DROP TABLE t92_w9_c14;
-- @s09_ddl_in_tx_rollback
DROP TABLE IF EXISTS t92_w9_c15; BEGIN; CREATE TABLE t92_w9_c15 (id INTEGER, PRIMARY KEY (id)); ROLLBACK; SELECT COUNT(*) FROM information_schema.tables WHERE table_name = 't92_w9_c15'; DROP TABLE IF EXISTS t92_w9_c15;
-- @s09_show_isolation_default
SHOW transaction_isolation;
-- @s09_set_transaction_isolation_serializable
BEGIN; SET TRANSACTION ISOLATION LEVEL SERIALIZABLE; SHOW transaction_isolation; COMMIT;
-- @s09_begin_isolation_serializable
BEGIN ISOLATION LEVEL SERIALIZABLE; SHOW transaction_isolation; COMMIT;
-- @s09_set_transaction_read_only_write
DROP TABLE IF EXISTS t92_w9_c19; CREATE TABLE t92_w9_c19 (id INTEGER, PRIMARY KEY (id)); BEGIN; SET TRANSACTION READ ONLY; INSERT INTO t92_w9_c19 VALUES (1); COMMIT; SELECT COUNT(*) FROM t92_w9_c19; DROP TABLE t92_w9_c19;
-- @s09_begin_read_only_write
DROP TABLE IF EXISTS t92_w9_c20; CREATE TABLE t92_w9_c20 (id INTEGER, PRIMARY KEY (id)); BEGIN READ ONLY; INSERT INTO t92_w9_c20 VALUES (1); COMMIT; SELECT COUNT(*) FROM t92_w9_c20; DROP TABLE t92_w9_c20;
-- @s09_start_transaction
DROP TABLE IF EXISTS t92_w9_c21; CREATE TABLE t92_w9_c21 (id INTEGER, PRIMARY KEY (id)); START TRANSACTION; INSERT INTO t92_w9_c21 VALUES (1); ROLLBACK; SELECT COUNT(*) FROM t92_w9_c21; DROP TABLE t92_w9_c21;
